"use client";

import { type HTMLAttributes, type KeyboardEvent, useEffect, useId, useMemo, useRef, useState } from "react";
import {
  addDays,
  addMonths,
  compareDays,
  isSameDay,
  isSameMonth,
  monthGrid,
  startOfDay,
  startOfMonth,
} from "../utils/date";
import { cx } from "../utils/cx";
import { ChevronLeftIcon, ChevronRightIcon } from "../icons/interface";

export type DateRange = { from?: Date; to?: Date };

type Shared = Omit<HTMLAttributes<HTMLDivElement>, "onChange" | "defaultValue"> & {
  /** Earliest and latest selectable day. */
  min?: Date;
  max?: Date;
  /** Mark more days unavailable. */
  isDisabled?: (day: Date) => boolean;
  /** 0 = Sunday, 1 = Monday. Default 0. */
  weekStartsOn?: 0 | 1;
  locale?: string;
  /** The month shown first (and the day that takes focus). Default: the selection, else today. */
  defaultMonth?: Date;
};
export type CalendarProps = Shared &
  (
    | { mode?: "single"; value?: Date | null; defaultValue?: Date | null; onValueChange?: (value: Date | null) => void }
    | { mode: "range"; value?: DateRange; defaultValue?: DateRange; onValueChange?: (value: DateRange) => void }
  );

/**
 * A month grid for picking a day or a range. Arrows move by day and week, Home/End go to the week's ends, PageUp and
 * PageDown change month (with Shift, year), Enter or Space picks. Changing month slides the grid the way you are
 * heading; hovering a range preview is drawn as you move. Every day button has its full date as its name.
 */
export function Calendar(props: CalendarProps) {
  const { min, max, isDisabled, weekStartsOn = 0, locale, defaultMonth, className, mode = "single", ...rest } = props;
  const { value: _v, defaultValue: _d, onValueChange: _o, ...attrs } = rest as Record<string, unknown>;
  const range = mode === "range";
  const initial = (props as { defaultValue?: Date | null | DateRange }).defaultValue;
  const [inner, setInner] = useState<Date | null | DateRange | undefined>(initial);
  const controlled = (props as { value?: Date | null | DateRange }).value;
  const value = controlled === undefined ? inner : controlled;
  const onValueChange = (props as { onValueChange?: (v: never) => void }).onValueChange;

  const sel = value as Date | null | undefined;
  const rng = (range ? (value ?? {}) : {}) as DateRange;
  const anchorDay = range ? (rng.from ?? rng.to) : sel;
  const today = useMemo(() => startOfDay(new Date()), []);
  const [month, setMonth] = useState(() => startOfMonth(defaultMonth ?? anchorDay ?? today));
  const [focusDay, setFocusDay] = useState(() => startOfDay(defaultMonth ?? anchorDay ?? today));
  const [direction, setDirection] = useState<"next" | "prev" | "none">("none");
  const [hover, setHover] = useState<Date | null>(null);
  const grid = useRef<HTMLDivElement>(null);
  const wantFocus = useRef(false);
  const labelId = useId();

  const monthLabel = new Intl.DateTimeFormat(locale, { month: "long", year: "numeric" });
  const dayLabel = new Intl.DateTimeFormat(locale, { weekday: "long", year: "numeric", month: "long", day: "numeric" });
  const weekdayLong = new Intl.DateTimeFormat(locale, { weekday: "long" });
  const weekdayShort = new Intl.DateTimeFormat(locale, { weekday: "short" });
  const weeks = useMemo(() => monthGrid(month, weekStartsOn), [month, weekStartsOn]);
  const headers = weeks[0] ?? [];

  const blocked = (d: Date) =>
    (min && compareDays(d, min) < 0) || (max && compareDays(d, max) > 0) || isDisabled?.(d) || false;
  const commit = (v: Date | null | DateRange) => {
    if (controlled === undefined) setInner(v);
    onValueChange?.(v as never);
  };
  const go = (to: Date) => {
    const target = startOfDay(to);
    if (!isSameMonth(target, month)) {
      setDirection(compareDays(target, month) > 0 ? "next" : "prev");
      setMonth(startOfMonth(target));
    }
    setFocusDay(target);
  };
  const pick = (d: Date) => {
    if (blocked(d)) return;
    setFocusDay(d);
    if (!range) {
      commit(isSameDay(sel, d) ? null : d);
      return;
    }
    if (!rng.from || rng.to) commit({ from: d });
    else commit(compareDays(d, rng.from) < 0 ? { from: d, to: rng.from } : { from: rng.from, to: d });
    setHover(null);
  };

  // move focus to the focused day after a keyboard move, once its month has rendered
  // biome-ignore lint/correctness/useExhaustiveDependencies: re-runs when the focused day or month changes
  useEffect(() => {
    if (!wantFocus.current) return;
    wantFocus.current = false;
    grid.current?.querySelector<HTMLElement>('[data-focus="true"]')?.focus();
  }, [focusDay, month]);

  const key = (e: KeyboardEvent<HTMLDivElement>) => {
    const step: Record<string, Date> = {
      ArrowLeft: addDays(focusDay, -1),
      ArrowRight: addDays(focusDay, 1),
      ArrowUp: addDays(focusDay, -7),
      ArrowDown: addDays(focusDay, 7),
      Home: addDays(focusDay, -((focusDay.getDay() - weekStartsOn + 7) % 7)),
      End: addDays(focusDay, 6 - ((focusDay.getDay() - weekStartsOn + 7) % 7)),
      PageUp: addMonths(focusDay, e.shiftKey ? -12 : -1),
      PageDown: addMonths(focusDay, e.shiftKey ? 12 : 1),
    };
    const to = step[e.key];
    if (!to) return;
    e.preventDefault();
    wantFocus.current = true;
    go(to);
  };

  const inPreview = (d: Date) => {
    if (!range || !rng.from || rng.to || !hover) return false;
    const [a, b] = compareDays(hover, rng.from) < 0 ? [hover, rng.from] : [rng.from, hover];
    return compareDays(d, a) >= 0 && compareDays(d, b) <= 0;
  };
  const inRange = (d: Date) => !!rng.from && !!rng.to && compareDays(d, rng.from) >= 0 && compareDays(d, rng.to) <= 0;

  const prevDisabled = !!min && compareDays(addDays(month, -1), min) < 0;
  const nextDisabled = !!max && compareDays(addMonths(month, 1), max) > 0;
  const shift = (n: number) => {
    setDirection(n > 0 ? "next" : "prev");
    setMonth(addMonths(month, n));
    setFocusDay((d) => addMonths(d, n));
  };

  return (
    <div {...(attrs as HTMLAttributes<HTMLDivElement>)} className={cx("hm-calendar", className)}>
      <div className="hm-calendar-head">
        <button
          type="button"
          className="hm-calendar-nav"
          aria-label="Previous month"
          disabled={prevDisabled}
          onClick={() => shift(-1)}
        >
          <ChevronLeftIcon size={14} strokeWidth={1.6} />
        </button>
        <p id={labelId} className="hm-calendar-title" aria-live="polite">
          {monthLabel.format(month)}
        </p>
        <button
          type="button"
          className="hm-calendar-nav"
          aria-label="Next month"
          disabled={nextDisabled}
          onClick={() => shift(1)}
        >
          <ChevronRightIcon size={14} strokeWidth={1.6} />
        </button>
      </div>
      <div className="hm-calendar-viewport">
        <div
          key={`${month.getFullYear()}-${month.getMonth()}`}
          ref={grid}
          role="grid"
          aria-labelledby={labelId}
          aria-multiselectable={range || undefined}
          className="hm-calendar-grid"
          data-direction={direction}
          onKeyDown={key}
          onPointerLeave={() => setHover(null)}
        >
          <div role="row" className="hm-calendar-row hm-calendar-weekdays">
            {headers.map((d) => (
              <span
                key={d.getDay()}
                role="columnheader"
                aria-label={weekdayLong.format(d)}
                className="hm-calendar-weekday"
              >
                {weekdayShort.format(d).slice(0, 2)}
              </span>
            ))}
          </div>
          {weeks.map((week) => (
            <div key={week[0]?.toISOString()} role="row" className="hm-calendar-row">
              {week.map((d) => {
                const outside = !isSameMonth(d, month);
                const selected = range ? isSameDay(d, rng.from) || isSameDay(d, rng.to) : isSameDay(d, sel);
                const off = blocked(d);
                const focused = isSameDay(d, focusDay);
                return (
                  <span
                    key={d.getTime()}
                    role="gridcell"
                    aria-selected={selected || undefined}
                    className="hm-calendar-cell"
                  >
                    <button
                      type="button"
                      tabIndex={focused ? 0 : -1}
                      data-focus={focused}
                      data-today={isSameDay(d, today) ? "" : undefined}
                      data-outside={outside ? "" : undefined}
                      data-selected={selected ? "" : undefined}
                      data-in-range={inRange(d) || inPreview(d) ? "" : undefined}
                      data-range-start={range && isSameDay(d, rng.from) ? "" : undefined}
                      data-range-end={range && isSameDay(d, rng.to) ? "" : undefined}
                      aria-label={dayLabel.format(d)}
                      aria-current={isSameDay(d, today) ? "date" : undefined}
                      disabled={off}
                      className="hm-calendar-day"
                      onClick={() => pick(d)}
                      onPointerEnter={() => range && setHover(d)}
                    >
                      {d.getDate()}
                    </button>
                  </span>
                );
              })}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
